/** The overview row's meta line. */
export function overviewMeta(locations: number): string {
  return locations === 1 ? '1 location' : `All ${formatCount(locations)} locations`
}

/** FR-22: the non-selectable line when more locations match than are drawn. */
export function narrowingLine(shown: number, matches: number): string {
  return `Showing ${formatCount(shown)} of ${formatCount(matches)} ${plural(matches, 'location', 'locations')}. Type to narrow.`
}

/** A picker row's checklist count. */
export function checklistCountLabel(n: number): string {
  return `${formatCount(n)} ${checklistsNoun(n)}`
}
/** "checklist" or "checklists", for a figure set in its own weight beside it. */
export function checklistsNoun(n: number): string {
  return plural(n, 'checklist', 'checklists')
}

/** A location's display name: the bounded name with the written ellipsis, or
 *  the placeholder for an empty name (FR-13). */
export function displayName(name: string, truncated: boolean): string {
  if (name === '') return UNNAMED_LOCATION
  return truncated ? name + ELLIPSIS : name
}

