export function rankUnit(list: 'checklists' | 'species', n: number): string {
  return list === 'species' ? 'species' : plural(n, 'checklist', 'checklists')
}

/** A ranked row's accessible name: its own visible text, in reading order and
 *  comma-separated, so it contains the visible name and figure (FR-30). */
export function rankRowLabel(parts: readonly string[], figure: number, unit: string): string {
  return [...parts, `${formatCount(figure)} ${unit}`].join(', ')
}

/** FR-30's degenerate form: one location, each list one sentence with a control. */
export function soleChecklistsParts(checklists: number): { before: string; after: string } {
  return checklists === 1
    ? { before: 'Your 1 checklist is at ', after: '.' }
    : { before: `All ${formatCount(checklists)} of your checklists are at `, after: '.' }
}
export function soleSpeciesParts(species: number): { before: string; after: string } {
  return species === 1
    ? { before: 'Your 1 species was recorded at ', after: '.' }
    : { before: `All ${formatCount(species)} species on your list were recorded at `, after: '.' }
}

