// The life list (FR-37, FR-38)

/** The count sentence, the list's caption; the figure apart so it takes 700. */
export function lifeListCaption(species: number, checklists: number): string {
  const c = formatCount(checklists)
  if (species === 1) {
    return checklists === 1
      ? ' species at this location, on your 1 checklist here.'
      : ` species at this location, with how many of your ${c} checklists here include it.`
  }
  return checklists === 1
    ? ' species at this location, newest first by the date you first recorded each one here, all on your 1 checklist here.'
    : ` species at this location, newest first by the date you first recorded each one here, with how many of your ${c} checklists here include it.`
}
export const COLUMN_HEADERS = {
  species: 'Species',
  first: 'First here',
  of: (checklists: number) => `Of ${formatCount(checklists)} ${plural(checklists, 'checklist', 'checklists')}`,
} as const
export const FIRST_RECORDED_SR = 'First recorded here'
/** The screen-reader words for a row's checklist figure. */
export function onChecklistsSr(n: number, checklists: number): string {
  return `On ${formatCount(n)} of ${formatCount(checklists)} ${plural(checklists, 'checklist', 'checklists')} here.`
}
/** The stacked row's visible words around the figure: "on {n} of {C} checklists". */
export const ON_WORD = 'on '
export function ofChecklistsTail(checklists: number): string {
  return ` of ${formatCount(checklists)} ${plural(checklists, 'checklist', 'checklists')}`
}
