/** FR-44: the share figure apart (it takes 600), then the sentence. */
export function completeSentence(complete: number, known: number, unknown: number): string {
  const says = plural(known, 'checklist that says', 'checklists that say')
  const tail = unknown > 0 ? ` ${formatCount(unknown)} ${plural(unknown, 'does', 'do')} not say.` : ''
  return ` complete: ${formatCount(complete)} of the ${formatCount(known)} ${says} whether every species was reported.${tail}`
}
export const NONE_SAY = 'None of your checklists here says whether every species was reported.'

// Weather (FR-45 to FR-49)

export const NO_WEATHER = 'None of your checklists here carries a weather block.'
/** FR-46: the readable figure apart, then the coverage sentence. */
export function weatherCoverage(readable: number, total: number, unreadable: number): string {
  const head = ` of your ${formatCount(total)} ${plural(total, 'checklist', 'checklists')} here ${plural(readable, 'carries', 'carry')} a weather block SnowRaven can read.`
  return unreadable > 0
    ? `${head} ${formatCount(unreadable)} more ${plural(unreadable, 'carries', 'carry')} a block it could not read.`
    : head
}
export function weatherBelowFloor(floor: number): string {
  return `That is too few to summarize. Sky, temperature, and wind are shown once ${formatCount(floor)} of your checklists here carry a block.`
}
